"""Промпты ВУ 4–6 для ChatGPT → prompty.md.  python3 builds/mvu_46/prompty_gen.py"""
import os
STYLE = ("Style: cute 2D cartoon illustration for children aged 4–6, the same style as the attached purple dragon picture — "
         "soft rounded shapes, clean smooth dark outlines, bright cheerful flat colours with gentle soft shading, friendly and warm. "
         "No text, no letters, no numbers, no logos, no watermark.")
REF_STYLE = "Use the attached purple dragon picture only as a STYLE reference (do not draw the dragon)."
SCENE = "Wide landscape 16:9 background picture, nobody in it: no people, no animals, no dragon (characters will be added separately)."
SHEET = ("Transparent background (or plain flat pure white background), wide empty gaps between the items, every item complete, "
         "centred in its own cell and not touching any other item or the edge.")
DRAGON = ("Use the attached purple dragon picture as the EXACT character reference: keep the very same character — the same purple colour, "
          "yellow belly, orange-yellow horns, small orange wings, flame on the tail tip, the same face, eyes and proportions. Do not redesign him.")
GRANNY = ("Use the attached picture of the old purple dragon granny (yellow headscarf, red coat, walking stick) as the EXACT character reference: "
          "keep the very same character, colours, face and clothes. Do not redesign her.")
P = []
def add(sec, name, title, body): P.append((sec, name, title, body))

# ── фоны
add('Фоны', 'map', 'карта сокровищ', REF_STYLE + " Wide landscape 16:9 picture of an old treasure map on crumpled warm-beige parchment, seen from above and filling the whole picture. Five small places drawn on the map, each with empty space around it and connected by dashed paths: a cosy little house with a red roof (bottom centre), a forest of round green trees (left), a park with a playground and a small pond (right), a jungle with palm trees and a big red X mark (top left), and a very small, pale planet with a ring drawn faintly in the bottom-right corner, almost hidden in the paper texture. A small compass rose in the top-right corner. No characters, no people, no animals. " + STYLE)
add('Фоны', 'room', 'детская комната', REF_STYLE + " " + SCENE + " A bright child's bedroom seen from the front: a bed on the left with a clear empty space under it, a wardrobe, a small desk with a chair, a shelf on the wall, a window with curtains and sunshine, a round rug on the floor. The room is tidy and has NO toys, NO clothes and NO school things anywhere — the floor, bed, desk and shelf are empty (objects will be added separately). " + STYLE)
add('Фоны', 'forest', 'лес', REF_STYLE + " " + SCENE + " A friendly sunny forest clearing: tall trees in the background, soft green grass, flowers, a small pond on the left. The right third of the picture is an open grassy area with NO tree (a big tree will be added there), and the front of the picture is empty grass (bushes will be added there). " + STYLE)
add('Фоны', 'park', 'парк', REF_STYLE + " " + SCENE + " A sunny city park: an empty wooden bench in the front left, a playground with a slide and a swing frame in the background, green trees, a path, a small pond with a little bridge, blue sky. Plenty of open space on the path and grass in the middle (children will be added separately). " + STYLE)
add('Фоны', 'launch', 'стартовая площадка', REF_STYLE + " " + SCENE + " Evening sky above a green hill with a small rocket launch pad in the centre — an empty launch pad, no rocket (the rocket will be added separately). First stars appear in the deep blue sky. " + STYLE)
add('Фоны', 'space', 'космос', REF_STYLE + " " + SCENE + " Deep space: a dark blue-violet starry sky with soft nebula clouds, completely empty in the middle — no planets, no rockets, no big stars (they will be added separately), only tiny distant twinkles. " + STYLE)
add('Фоны', 'planet_red', 'красная планета, крупно', REF_STYLE + " " + SCENE + " The surface of a warm red-orange desert planet seen up close: smooth sand dunes and round red rocks in the front, a big orange planet and a small ringed planet in the pink sky. The front centre is an empty flat place (a postcard will be added there). " + STYLE)
add('Фоны', 'planet_ice', 'ледяная планета, крупно', REF_STYLE + " " + SCENE + " The surface of a calm blue ice planet seen up close: a cold blue sea with small white ice floes, snowy hills on the horizon, pale sky with stars. Nothing else in the picture. " + STYLE)
add('Фоны', 'planet_moon', 'серая планета, крупно', REF_STYLE + " " + SCENE + " The grey surface of a moon seen up close: soft round craters, black starry sky. The middle of the ground is empty and flat (a rocket will be added standing there). " + STYLE)
add('Фоны', 'planet_earth', 'Земля, крупно', REF_STYLE + " " + SCENE + " A bright green meadow on Earth seen up close: rolling hills, flowers, a few round trees, a path, a big friendly yellow sun in the sky above the middle, white clouds. " + STYLE)
add('Фоны', 'jungle', 'джунгли', REF_STYLE + " " + SCENE + " A magical jungle: a waterfall and a small river on the left, big leaves, vines and tropical flowers, warm light through the leaves. The front centre is an open flat patch of ground (a treasure chest will be added there). " + STYLE)

# ── предметы листами
add('Предметы листами', 'sheet_keys', 'четыре ключа', REF_STYLE + " A row of 4 big old-fashioned fairy-tale keys, each with a round decorated head. Row 1, left to right: red key, blue key, green key, yellow key. All four keys the same shape and size, lying horizontally. " + SHEET + " " + STYLE)
add('Предметы листами', 'sheet_toys', 'игрушки и школьные вещи', REF_STYLE + " A sheet of 8 separate objects in a 4×2 grid. Row 1, left to right: a red toy car, a colourful ball, a doll, a toy robot. Row 2, left to right: a toy plane, a pencil, a book, a ruler. " + SHEET + " " + STYLE)
add('Предметы листами', 'sheet_clothes', 'одежда, мишка, рюкзак', REF_STYLE + " A sheet of 8 separate objects in a 4×2 grid. Row 1, left to right: a yellow T-shirt, a pair of striped socks, a hat, a pair of sneakers. Row 2, left to right: a brown teddy bear sitting, an open empty school backpack (front view), an open empty wooden toy box (front view), a small rug. " + SHEET + " " + STYLE)
add('Предметы листами', 'sheet_animals1', 'лесные животные 1', REF_STYLE + " A sheet of 4 separate forest animals in a 2×2 grid, each sitting and facing the viewer, friendly and cute. Row 1, left to right: a fox, a rabbit. Row 2, left to right: an owl, a hedgehog. " + SHEET + " " + STYLE)
add('Предметы листами', 'sheet_animals2', 'лесные животные 2', REF_STYLE + " A sheet of 4 separate animals in a 2×2 grid, friendly and cute. Row 1, left to right: a brown bear, a squirrel. Row 2, left to right: a small blue butterfly with open wings, a small yellow bird. " + SHEET + " " + STYLE)
add('Предметы листами', 'sheet_pairs', 'животные парами', REF_STYLE + " A sheet of 4 separate pairs of animals in a 2×2 grid — in every cell exactly TWO of the same animal sitting side by side. Row 1, left to right: two kittens, two ducks. Row 2, left to right: two frogs, two little rabbits. " + SHEET + " " + STYLE)
add('Предметы листами', 'sheet_bushes', 'кусты', REF_STYLE + " A row of 3 separate big round green leafy bushes, each a little different in shape, wide and dense enough to hide a fox behind it. " + SHEET + " " + STYLE)
add('Предметы', 'tree', 'большое дерево', REF_STYLE + " One big friendly tree with a thick trunk and a round green crown, with one long strong branch sticking out to the left (a key on a rope will hang from it). The whole tree is visible from the roots to the top. Nothing else in the picture. Transparent background (or plain flat pure white background), the tree not touching the edges. " + STYLE)
add('Предметы листами', 'sheet_food', 'еда и тарелка', REF_STYLE + " A sheet of 9 separate objects in a 3×3 grid. Row 1, left to right: a pizza, broccoli, an ice cream cone. Row 2, left to right: a fish on a small plate, a birthday cake, a red apple. Row 3, left to right: a banana, a carrot, a big empty white plate. " + SHEET + " " + STYLE)
add('Предметы листами', 'sheet_kids', 'дети в парке', REF_STYLE + " A sheet of 6 separate animated cartoon children, about six years old, full body, in a 3×2 grid, each doing one clear action. Row 1, left to right: a boy running, a girl jumping with a skipping rope, a boy riding a bike. Row 2, left to right: a girl on a swing (with the swing seat and ropes), a boy kicking a football, a girl eating an ice cream. " + SHEET + " " + STYLE)
add('Предметы листами', 'sheet_space', 'планеты, ракета, открытка', REF_STYLE + " A sheet of 8 separate objects in a 4×2 grid. Row 1, left to right: a red planet, a blue planet with wavy stripes, the planet Earth, a grey moon with craters. Row 2, left to right: a small pale planet with a ring, a white-and-red cartoon rocket standing upright, a picture postcard showing a sea and a sun (no writing), a smiling yellow star. " + SHEET + " " + STYLE)
add('Предметы листами', 'sheet_chest', 'сундук и книга', REF_STYLE + " A sheet of 3 separate objects in a row. Left to right: a closed wooden pirate treasure chest with gold trim and FOUR keyholes on the front — a red one, a blue one, a green one and a yellow one; the same chest wide open with golden light shining out; a thick magic book with a plain purple cover glowing with golden sparkles (no writing on the cover). " + SHEET + " " + STYLE)

# ── Дракоша и бабушка
add('Дракоша и бабушка', 'dragon_wave', 'Дракоша машет (2 кадра)', DRAGON + " Draw him TWICE side by side as two frames of a waving animation, identical in everything except the right arm: left frame — the arm raised with the palm open, right frame — the same arm raised higher and tilted the other way. Both frames full body, same size, same position. " + SHEET + " " + STYLE)
add('Дракоша и бабушка', 'dragon_moves', 'Дракоша идёт и прыгает от радости', DRAGON + " A sheet of 4 frames in a row, full body, same size: walking to the right with the left foot forward; walking to the right with the right foot forward; crouching happily before a jump; jumping high with joy, arms up, holding a key in one hand. " + SHEET + " " + STYLE)
add('Дракоша и бабушка', 'dragon_says', 'Дракоша показывает действия', DRAGON + " A sheet of 6 poses in a 3×2 grid, full body, each a clear action for the game 'Dragon says'. Row 1, left to right: jumping, swimming in a little splash of water, flying with his small wings spread. Row 2, left to right: running, dancing, clapping his hands. " + SHEET + " " + STYLE)
add('Дракоша и бабушка', 'dragon_moods', 'Дракоша: грустит, думает, показывает, держит книгу', DRAGON + " A sheet of 4 poses in a row, full body, same size: sad with a little frown; thinking with a finger on his chin; pointing to the side with one hand; happily holding up a thick open book glowing with golden sparkles. " + SHEET + " " + STYLE)
add('Дракоша и бабушка', 'dragon_space', 'Дракоша-космонавт', DRAGON + " Draw him as a little astronaut: a white space suit and a round clear glass helmet, his horns and face visible inside. Two poses side by side, full body: standing and waving; floating in the air with arms spread happily. " + SHEET + " " + STYLE)
add('Дракоша и бабушка', 'granny_hungry', 'бабушка голодная (2 кадра)', GRANNY + " She is sitting (as if on a bench), sad and hungry, holding her tummy with one hand. Draw her TWICE side by side as two frames, identical except for one tear: in the left frame a small tear sits in the corner of her eye, in the right frame the tear has rolled down her cheek. " + SHEET + " " + STYLE)
add('Дракоша и бабушка', 'granny_moods', 'бабушка ест, морщится, отдаёт ключ', GRANNY + " A sheet of 3 poses in a row, sitting (as if on a bench), same size: happily eating with a fork, eyes closed with pleasure; frowning and turning her head away with a 'yuck' face; smiling and holding out a green key with both hands. " + SHEET + " " + STYLE)

out = ['# ВУ 4–6 · Wow Dragon — промпты для ChatGPT (26.11.2026)', '',
       'Игры (решение Анны 24.11, «51»): А «Что пропало?», Б «Где мишка?», В «Кто прячется в кустах?», Д «Потряси дерево», '
       'Е «Покорми бабушку», Ж «Дракоша говорит», И отсчёт и звёзды (космос проходят все: слабые считают звёзды, сильные ещё и разбирают планеты), К ключи по цвету.', '',
       'К каждому промпту прикладывать `obrazcy/drakosha_obrazec.png`; к промптам бабушки — `obrazcy/babushka_obrazec.png`. '
       'Фоны — горизонтальные. Анимация героев — из кадров (машет, слеза, шаги), остальное двигает сам урок.', '']
sec = None; n = 0
for s, name, title, body in P:
    if s != sec: out += ['## ' + s, '']; sec = s
    n += 1
    out += [f'### {n} · {title} → `{name}`', '', '```', body, '```', '']
open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'prompty.md'), 'w').write('\n'.join(out))
print(n, 'prompts')
